import{_ as n,o as i,c as t,a2 as a}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"Incident evidence","description":"Mobile Inspector development documentation · Incident evidence","frontmatter":{"title":"Incident evidence","description":"Mobile Inspector development documentation · Incident evidence"},"headers":[],"relativePath":"en/reference/incidents.md","filePath":"en/reference/incidents.md"}'),s={name:"en/reference/incidents.md"};function o(d,e,c,r,l,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="incident-evidence" tabindex="-1">Incident evidence <a class="header-anchor" href="#incident-evidence" aria-label="Permalink to &quot;Incident evidence&quot;">​</a></h1><p>Rules identify candidate observations, not established client defects. HTTP failure, configured business rejection, expected cancellation and missing evidence remain distinct.</p><h2 id="evidence-windows" tabindex="-1">Evidence windows <a class="header-anchor" href="#evidence-windows" aria-label="Permalink to &quot;Evidence windows&quot;">​</a></h2><p>Each incident retains up to 120 references from the preceding 30 seconds and 80 from the following 10 seconds, at most 200 total. Host receipt time controls windows; a device clock cannot extend them. Matching fingerprints merge inside the original deadline. A closed window emits readiness once even if no later event arrives.</p><p>Retention is 100 incidents per project and 400 per instance. Clear, revoke, expiry and generation changes remove derived records and invalidate callbacks. There are no disk incident snapshots.</p><h2 id="completeness-and-meaning" tabindex="-1">Completeness and meaning <a class="header-anchor" href="#completeness-and-meaning" aria-label="Permalink to &quot;Completeness and meaning&quot;">​</a></h2><p>Latency uses finite duration/elapsed values on response or complete summaries; first-byte time is not total latency. An error without a code yields generic network failure, without guessing cause from free text. Unknown codes remain unclassified; cancellation is informational and not automatic defect evidence.</p><p>Gaps include truncated windows, sequence gaps, capture limits, unavailable evidence and incident limits. A known build mapping is provenance, not proof of source contents or line numbers. Missing or ambiguous mapping stays explicit.</p><p>Lists and details are project/generation scoped, default 50 items and maximum 200 with a bounded byte budget. Summary is default. Approved bodies require current permission on every read. See <a href="./mcp">MCP pagination</a> and <a href="./diagnosis">diagnosis lifecycle</a>.</p>',9)])])}const f=n(s,[["render",o]]);export{u as __pageData,f as default};
